622	final class GraphicPreviewPlayer {
623	    enum Subject {
624	        case module(GraphicModule, name: String, meta: [String: Any])
625	        case failed(name: String, [GraphicDiagnostic])
626	    }
627	
628	    /// What the thread and main share, under `condition`.
629	    private final class State {
630	        let condition = NSCondition()
631	        var subject: Subject?
632	        var generation = 0
633	        var stopped = false
634	        var framesDrawn = 0
635	        var drewOnMain = false
636	    }
637	
638	    private let state = State()
639	    private let canvas: CanvasSnapshot
640	    private let onFrame: (CGImage) -> Void
641	    /// The render thread, once the first `play` has started it.
642	    private(set) var thread: Thread?
643	
644	    init(canvas: CanvasSnapshot, onFrame: @escaping (CGImage) -> Void) {
645	        self.canvas = canvas
646	        self.onFrame = onFrame
647	    }
648	
649	    deinit { stop() }
650	
651	    /// Plays `subject` from its frame 0, or nothing for nil. Main.
652	    func play(_ subject: Subject?) {
653	        state.condition.lock()
654	        let stopped = state.stopped
655	        state.subject = subject
656	        state.generation += 1
657	        state.condition.broadcast()
658	        state.condition.unlock()
659	        guard !stopped, thread == nil else { return }
660	        let state = self.state
661	        let canvas = self.canvas
662	        let made = Thread { [weak self] in
663	            Self.run(state, canvas) { image, generation in
664	                DispatchQueue.main.async { self?.deliver(image, generation) }
665	            }
666	        }
667	        made.stackSize = GraphicPrefetch.workerStackBytes
668	        made.qualityOfService = .userInitiated
669	        made.name = "framejob.graphic-preview"
670	        thread = made
671	        made.start()
672	    }
673	
674	    /// Ends the render thread; a later `play` does nothing. Main.
675	    func stop() {
676	        state.condition.lock()
677	        state.stopped = true
678	        state.subject = nil
679	        state.condition.broadcast()
680	        state.condition.unlock()
681	    }
682	
683	    /// Frames drawn so far, and whether any was drawn on the main thread
684	    /// (the probe's read of "off main"). Any thread.
685	    var drawn: (frames: Int, onMain: Bool) {
686	        state.condition.lock()
687	        defer { state.condition.unlock() }
688	        return (state.framesDrawn, state.drewOnMain)
689	    }
690	
691	    /// Main: hands `image` on when it is still the newest subject's.
692	    private func deliver(_ image: CGImage, _ generation: Int) {
693	        state.condition.lock()
694	        let current = !state.stopped && state.generation == generation
695	        state.condition.unlock()
696	        if current { onFrame(image) }
697	    }
698	
699	    // MARK: - The thread
700	
701	    private static func run(
702	        _ state: State, _ canvas: CanvasSnapshot, _ deliver: (CGImage, Int) -> Void
703	    ) {
704	        var playing = -1
705	        var subject: Subject?
706	        var start = Date()
707	        var cardShown = false
708	        while true {
709	            state.condition.lock()
710	            while !state.stopped && state.subject == nil { state.condition.wait() }
711	            if state.stopped {
712	                state.condition.unlock()
713	                return
714	            }
715	            if state.generation != playing {
716	                playing = state.generation
717	                subject = state.subject
718	                start = Date()
719	                cardShown = false
720	            }
721	            state.condition.unlock()
722	            guard let current = subject else { continue }
723	
724	            let fps = max(canvas.fps.double, 1)
725	            var next = Date().addingTimeInterval(1 / fps)
726	            switch current {
727	            case .failed(let name, let diagnostics):
728	                if !cardShown {
729	                    let text = LayerRenderers.errorCardText(
730	                        name: name, frame: nil, diagnostic: diagnostics.first)
731	                    if let image = card(text, width: canvas.width, height: canvas.height) {
732	                        record(state)
733	                        deliver(image, playing)
734	                    }
735	                    cardShown = true
736	                }
737	                next = .distantFuture
738	            case .module(let module, let name, let meta):
739	                let size = Self.size(meta, name, canvas)
740	                let length = Self.length(meta, name, fps: fps)
741	                let elapsed = Date().timeIntervalSince(start)
742	                let absolute = Int((elapsed * fps).rounded(.down))
743	                let frame = absolute % length
744	                if let image = Self.frame(
745	                    module, name: name, frame: frame, length: length, size: size, canvas: canvas)
746	                {
747	                    record(state)
748	                    deliver(image, playing)
749	                }
750	                next = start.addingTimeInterval(Double(absolute + 1) / fps)
751	                if next <= Date() {
752	                    next = start.addingTimeInterval(
753	                        (Date().timeIntervalSince(start) * fps).rounded(.up) / fps)
754	                }
755	            }
756	            state.condition.lock()
757	            if !state.stopped && state.generation == playing {
758	                _ = state.condition.wait(until: next)
759	            }
760	            state.condition.unlock()
761	        }
762	    }
763	
764	    private static func record(_ state: State) {
765	        state.condition.lock()
766	        state.framesDrawn += 1
767	        if Thread.isMainThread { state.drewOnMain = true }
768	        state.condition.unlock()
769	    }
