771	    /// The module's size: `meta` width and height, else the canvas's.
772	    private static func size(
773	        _ meta: [String: Any], _ name: String, _ canvas: CanvasSnapshot
774	    ) -> (width: Int, height: Int) {
775	        let width = try? AgentServer.metaWhole(meta, "width", name, in: AgentServer.sides)
776	        let height = try? AgentServer.metaWhole(meta, "height", name, in: AgentServer.sides)
777	        return (width ?? canvas.width, height ?? canvas.height)
778	    }
779	
780	    /// `meta.durationInFrames`, else 5 s at `fps`, ceiled.
781	    private static func length(_ meta: [String: Any], _ name: String, fps: Double) -> Int {
782	        let declared = try? AgentServer.metaWhole(
783	            meta, "durationInFrames", name, in: 1...1_000_000)
784	        return max(declared ?? Int((5 * fps).rounded(.up)), 1)
785	    }
786	
787	    /// One frame over the checker, or its error card.
788	    private static func frame(
789	        _ module: GraphicModule, name: String, frame: Int, length: Int,
790	        size: (width: Int, height: Int), canvas: CanvasSnapshot
791	    ) -> CGImage? {
792	        let ctx = AgentServer.graphicContext(
793	            frame: frame, fps: canvas.fps, length: length, width: size.width,
794	            height: size.height, canvas: canvas)
795	        let ctxJSON = (try? JSONSerialization.data(withJSONObject: ctx))
796	            .map { String(decoding: $0, as: UTF8.self) } ?? "{}"
797	        do {
798	            let drawn = try module.svg(
799	                frame: frame, propsJSON: "{}", ctxJSON: ctxJSON,
800	                budgetMs: GraphicRegistry.previewBudgetMs)
801	            let raster = try module.library.rasterize(
802	                drawn.svg, width: size.width, height: size.height)
803	            guard let picture = raster.cgImage(),
804	                let context = Self.context(size.width, size.height)
805	            else { return nil }
806	            GraphicContactSheet.paintChecker(context, width: size.width, height: size.height)
807	            context.draw(picture, in: CGRect(x: 0, y: 0, width: size.width, height: size.height))
808	            return context.makeImage()
809	        } catch {
810	            let text = LayerRenderers.errorCardText(
811	                name: name, frame: frame, diagnostic: GraphicDiagnostic.of(error).first)
812	            return card(text, width: size.width, height: size.height)
813	        }
814	    }
