816	    private static func card(_ text: String, width: Int, height: Int) -> CGImage? {
817	        guard let context = Self.context(width, height) else { return nil }
818	        LayerRenderers.paintErrorCard(
819	            text, in: context, bounds: CGRect(x: 0, y: 0, width: width, height: height))
820	        return context.makeImage()
821	    }
