825	        guard width > 0, height > 0, let space = CGColorSpace(name: CGColorSpace.sRGB) else {
826	            return nil
827	        }
828	        return CGContext(
829	            data: nil, width: width, height: height, bitsPerComponent: 8, bytesPerRow: 0,
830	            space: space,
