/// File ▸ Rename Graphic…, Delete Graphic… and Restore Graphic Version…
/// (spec §11 G-30; issue #103, issue batch B84): three menu actions, the
/// one place their sheet goes up, and their validator arm. The sheet,
/// `GraphicFileSheetController`, calls the bodies the three tools call
/// (`ProjectDocument+GraphicFiles.swift`); nothing here writes a file or
/// applies an op.
///
/// **Where a sheet opens** (G-30 (d)): Rename and Restore on the graphic of
/// the ONE selected clip when it is a row, else the first; Delete always on
/// the first. `selectedClips` is the open scope's selection.
///
/// **When an item is live** (G-30 (f)): something to list, and for Rename
/// no nest open. `validateGraphicMenuAction`'s default arm forwards here;
/// the frozen file's validator has already answered false with a sheet
/// attached. On every menu open Rename and Delete ask the last scan, and
/// Restore `keptNames()`: file names under `graphics/history/`, no bytes.
extension EditorViewController {

    /// File ▸ Rename Graphic… — `rename_graphic`'s body.
    @objc func renameGraphic(_ sender: Any?) {
        presentGraphicFileSheet(.rename)
    }

    /// File ▸ Delete Graphic… — `delete_graphic`'s body.
    @objc func deleteGraphic(_ sender: Any?) {
        presentGraphicFileSheet(.delete)
    }

    /// File ▸ Restore Graphic Version… — `restore_graphic`'s body, the
    /// newest kept text.
    @objc func restoreGraphicVersion(_ sender: Any?) {
        presentGraphicFileSheet(.restore)
    }

    /// The sheet for `act`, or a beep when the item has nothing to offer.
    func presentGraphicFileSheet(_ act: GraphicFileAct) {
        guard let document = document, GraphicFileSheetController.isOffered(act, in: document)
        else {
            NSSound.beep()
            return
        }
        let choices = GraphicFileSheetController.choices(for: act, in: document)
        let clips = selectedClips
        let selected = clips.count == 1 ? clips[0].graphic?.name : nil
        let sheet = GraphicFileSheetController(
            document: document, act: act, choices: choices,
            opening: GraphicFileSheetController.opening(for: act, selected: selected, in: choices))
        presentAsSheet(sheet)
    }

    /// The menu arm for the three; nil for any other action.
    func validateGraphicFileAction(_ action: Selector) -> Bool? {
        let act: GraphicFileAct
        switch action {
        case #selector(renameGraphic(_:)): act = .rename
        case #selector(deleteGraphic(_:)): act = .delete
        case #selector(restoreGraphicVersion(_:)): act = .restore
        default: return nil
        }
        guard let document = document else { return false }
        return GraphicFileSheetController.isOffered(act, in: document)
    }
}
// app/Sources/GraphicStore+Manual.swift — the graphics reference written
// into a package's `graphics/` (road map 10's G4a): `API.md` and `API.d.ts`,
// copies of the app's bundled `GraphicsAPI.md` and `GraphicsAPI.d.ts`, so an
// agent or a person editing the folder has the API beside the modules.
//
// **The manual is never a reason to create `graphics/`** (spec §11 G-14):
// `writeManual()` writes nothing unless the folder already exists, and
// `holdsContent` does not count the manual, so an untitled root holding only
// the manual is not carried by a save.

import Foundation

extension GraphicStore {
    /// What the manual is called inside `graphics/`.
    static let manualNames = ["API.md", "API.d.ts"]
    /// What it is called in the app's Resources, in `manualNames`' order.
    static let bundledManualNames = ["GraphicsAPI.md", "GraphicsAPI.d.ts"]

    /// The directory holding `Fonts/`, which holds the manual too. The
    /// harness copies the manual there; the probes copy none, so for them
    /// `writeManual()` is a no-op.
    static func manualDirectory(besideFonts fonts: URL) -> URL {
        fonts.deletingLastPathComponent()
    }

    var manualDirectory: URL { Self.manualDirectory(besideFonts: bundledFonts) }

    /// The app bundle's own `GraphicsAPI.md`, no document involved:
    /// `graphic_reference` answers it and Help ▸ Graphics Reference opens it.
    static var bundledReferenceURL: URL {
        manualDirectory(besideFonts: ProjectDocument.bundledFontsDirectory)
            .appendingPathComponent(bundledManualNames[0])
    }

    /// Main. Nothing unless `folderURL` exists; each file written
    /// (`.atomic`) only when its bytes differ from the bundled one; a
    /// bundled file that is absent is skipped silently.
    func writeManual() {
        let files = FileManager.default
        guard files.fileExists(atPath: folderURL.path) else { return }
        for (bundled, name) in zip(Self.bundledManualNames, Self.manualNames) {
            guard let bytes = try? Data(
                contentsOf: manualDirectory.appendingPathComponent(bundled))
            else { continue }
            let target = folderURL.appendingPathComponent(name)
            if let current = try? Data(contentsOf: target), current == bytes { continue }
            try? bytes.write(to: target, options: .atomic)
        }
    }

    /// True when `folder` holds ANY entry, file or directory, that is
    /// neither hidden, one of `manualNames`, nor a `.partial`. A `fonts/` or
    /// `assets/` subfolder counts; `listing(_:)`'s regular-files rule is not
    /// this.
    static func holdsContent(_ folder: URL) -> Bool {
        let entries = (try? FileManager.default.contentsOfDirectory(
            at: folder, includingPropertiesForKeys: nil,
            options: [.skipsHiddenFiles])) ?? []
        return entries.contains {
            !manualNames.contains($0.lastPathComponent) && $0.pathExtension != "partial"
        }
    }
}
